'use client';

import { useCallback, useEffect, useId, useRef, useState } from 'react';

import { useIsNarrow } from '@/registry/ndeko/hooks/use-is-narrow';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { InlineSheet } from '@/registry/ndeko/ui/inline-sheet';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import type { Manager, InstallTab } from './data';
import { DocPage } from './doc-page';
import { DocsHeader } from './docs-header';
import { DocsNav } from './docs-nav';
import { HomePage } from './home-page';
import { initCommandOf } from './install';
import { pageOf, type DocPage as DocPageContent, type PageId } from './pages';
import { searchOf, type SearchResult } from './search';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  TOP,
  type Route,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** A heading counts as read once it rises above this line of the frame. */
const READ_LINE_PX = 96;

/** Where a heading lands after a jump, just under the read line. */
const LANDING_PX = 64;

const COPIED_FOR_MS = 1600;

/** The width of the `@3xl` container step, where the sidebar takes the place of the sheet. */
const SIDEBAR_FROM_REM = 48;

function scrollBehaviorOf(shouldReduceMotion: boolean): ScrollBehavior {
  if (shouldReduceMotion) {
    return 'auto';
  }
  return 'smooth';
}

function docPageOf(route: Route): DocPageContent | null {
  if (route === 'home') {
    return null;
  }
  return pageOf(route);
}

function headingOfResult(result: SearchResult) {
  return result.entry.headingId ?? undefined;
}

/** The heading the rail marks, once the page it belongs to is the one on screen. */
function activeHeadingOf(page: DocPageContent, activeId: string) {
  const isOnPage = page.sections.some((section) => section.id === activeId);
  if (isOnPage) {
    return activeId;
  }
  return page.sections[0].id;
}

function readHeadingOf(frame: HTMLElement, fallback: string) {
  const frameTop = frame.getBoundingClientRect().top;
  const headings = frame.querySelectorAll<HTMLElement>('[data-heading]');
  let active = fallback;
  for (const heading of headings) {
    const top = heading.getBoundingClientRect().top - frameTop;
    const isRead = top <= READ_LINE_PX;
    const id = heading.dataset.heading;
    if (isRead && id) {
      active = id;
    }
  }
  return active;
}

export default function Marketing06() {
  const {
    ref,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
    takeOver,
  } = useSession(SESSION);
  const shouldReduceMotion = usePrefersReducedMotion();
  const isNarrow = useIsNarrow(ref, SIDEBAR_FROM_REM);
  const baseId = useId();
  const frameRef = useRef<HTMLDivElement>(null);
  const pendingFrame = useRef<number | null>(null);
  const [activeId, setActiveId] = useState('');
  const page = docPageOf(state.route);
  const isHome = page === null;
  const hasSidebar = !isHome;
  const canShowSheet = isNarrow && hasSidebar;
  const isSheetShown = canShowSheet && state.isNavOpen;
  const canReplay = isFinished && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, state.spoken);
  const searchId = `${baseId}-search`;

  const headingIdOf = useCallback(
    (headingId: string) => `${baseId}-${headingId}`,
    [baseId]
  );

  const scrollFrameTo = useCallback(
    (headingId: string) => {
      const frame = frameRef.current;
      const behavior = scrollBehaviorOf(shouldReduceMotion);
      if (!frame) {
        return null;
      }
      if (headingId === TOP) {
        frame.scrollTo({ top: 0, behavior: 'auto' });
        return null;
      }
      const selector = `[data-heading="${headingId}"]`;
      const heading = frame.querySelector<HTMLElement>(selector);
      if (!heading) {
        return null;
      }
      const headingTop = heading.getBoundingClientRect().top;
      const frameTop = frame.getBoundingClientRect().top;
      const top = headingTop - frameTop + frame.scrollTop - LANDING_PX;
      frame.scrollTo({ top, behavior });
      return heading;
    },
    [shouldReduceMotion]
  );

  useEffect(() => {
    if (state.readRequest === 0) {
      return;
    }
    scrollFrameTo(state.readTo);
  }, [state.readRequest, state.readTo, scrollFrameTo]);

  useEffect(() => {
    if (!state.isCommandCopied) {
      return;
    }
    const timer = setTimeout(() => {
      act({ type: 'commandReset' });
    }, COPIED_FOR_MS);
    return () => clearTimeout(timer);
  }, [state.isCommandCopied, act]);

  useEffect(() => {
    return () => {
      const frameRequest = pendingFrame.current;
      if (frameRequest !== null) {
        cancelAnimationFrame(frameRequest);
      }
    };
  }, []);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /** The page changes under the pointer of a person, so the keyboard starts reading from the top of the new one. */
  function startReading() {
    focusLater('[data-frame]');
  }

  function openPage(pageId: PageId) {
    act({ type: 'opened', route: pageId });
    startReading();
  }

  function openHome() {
    act({ type: 'opened', route: 'home' });
    startReading();
  }

  function openResult(result: SearchResult) {
    const heading = headingOfResult(result);
    act({ type: 'opened', route: result.entry.pageId, heading });
    startReading();
  }

  function openFirstResult() {
    const [first] = searchOf(state.query);
    if (first) {
      openResult(first);
    }
  }

  function search(query: string) {
    act({ type: 'searched', query });
  }

  function measureReading() {
    pendingFrame.current = null;
    const frame = frameRef.current;
    if (frame && page) {
      const first = page.sections[0].id;
      setActiveId(readHeadingOf(frame, first));
    }
  }

  /** The rail follows the scroll at most once a frame. */
  function followReading() {
    if (pendingFrame.current !== null) {
      return;
    }
    pendingFrame.current = requestAnimationFrame(measureReading);
  }

  function yieldToWheel() {
    if (isAutoplaying) {
      takeOver();
    }
  }

  /** A jump also hands the focus to the heading, so the keyboard reads on from there. */
  function jumpTo(headingId: string) {
    const heading = scrollFrameTo(headingId);
    heading?.focus({ preventScroll: true });
  }

  async function copyCommand() {
    try {
      const command = initCommandOf(state.manager);
      await navigator.clipboard.writeText(command);
    } catch {
      return;
    }
    act({ type: 'commandCopied' });
  }

  function openSheet() {
    act({ type: 'nav', isOpen: true });
    focusLater('[data-sheet-nav] input');
  }

  function closeSheet() {
    act({ type: 'nav', isOpen: false });
    focusLater('[data-sheet-trigger]');
  }

  function replay() {
    frameRef.current?.scrollTo({ top: 0 });
    restart();
  }

  const install = {
    manager: state.manager,
    tab: state.installTab,
    isCommandCopied: state.isCommandCopied,
    pressed,
    onPickManager: (manager: Manager) =>
      act({ type: 'managerPicked', manager }),
    onPickTab: (tab: InstallTab) => act({ type: 'tabPicked', tab }),
    onCopyCommand: copyCommand,
  };

  const nav = page && (
    <DocsNav
      searchId={searchId}
      query={state.query}
      pageId={page.id}
      pressed={pressed}
      onSearch={search}
      onEnter={openFirstResult}
      onOpenResult={openResult}
      onOpenPage={openPage}
    />
  );

  return (
    <div
      ref={ref}
      className='bg-background text-foreground @container relative flex h-dvh min-h-[36rem] w-full flex-col overflow-hidden'
    >
      <div inert={isSheetShown} className='flex min-h-0 flex-1 flex-col'>
        <DocsHeader
          isHome={isHome}
          pressed={pressed}
          canReplay={canReplay}
          onOpenHome={openHome}
          onOpenMenu={openSheet}
          onReplay={replay}
        />
        <div className='flex min-h-0 flex-1'>
          {!isHome && (
            <aside
              aria-label='Sidebar'
              className='hairline-r border-border hidden w-64 shrink-0 overflow-y-auto p-4 @3xl:block'
            >
              {!isNarrow && nav}
            </aside>
          )}
          <div
            ref={frameRef}
            data-frame
            tabIndex={-1}
            onScroll={followReading}
            onWheel={yieldToWheel}
            className='relative min-h-0 flex-1 overflow-y-auto overscroll-contain outline-none'
          >
            {isHome && (
              <HomePage
                searchId={searchId}
                query={state.query}
                pressed={pressed}
                onSearch={search}
                onEnter={openFirstResult}
                onOpenResult={openResult}
                onOpenPage={openPage}
              />
            )}
            {page && (
              <DocPage
                page={page}
                activeId={activeHeadingOf(page, activeId)}
                pressed={pressed}
                install={install}
                headingIdOf={headingIdOf}
                onJump={jumpTo}
                onOpenPage={openPage}
                onOpenHome={openHome}
              />
            )}
          </div>
        </div>
      </div>
      <InlineSheet
        side='start'
        isOpen={isSheetShown}
        onClose={closeSheet}
        label='Docs'
        closeLabel='Close the docs menu'
        className='z-40 @3xl:hidden'
        panelClassName='gap-2 overflow-y-auto p-3'
      >
        <div data-sheet-nav className='px-1 pb-2'>
          {isNarrow && nav}
        </div>
      </InlineSheet>
      <LiveRegion message={message} />
    </div>
  );
}

import {
  InfoIcon,
  LightbulbIcon,
  TriangleAlertIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';

import type { Tone } from './pages';

const TRAY: Record<Tone, string> = {
  info: 'bg-info/10',
  warning: 'bg-warning/10',
  tip: 'bg-success/10',
};

const GLYPH_TONE: Record<Tone, string> = {
  info: 'text-info-foreground',
  warning: 'text-warning-foreground',
  tip: 'text-success-foreground',
};

const GLYPH: Record<Tone, Icon> = {
  info: InfoIcon,
  warning: TriangleAlertIcon,
  tip: LightbulbIcon,
};

const WORD: Record<Tone, string> = {
  info: 'Note',
  warning: 'Warning',
  tip: 'Tip',
};

type CalloutProps = {
  tone: Tone;
  children: React.ReactNode;
};

export function Callout({ tone, children }: CalloutProps) {
  const ToneIcon = GLYPH[tone];

  return (
    <div
      className={cn(
        'flex items-start gap-3 rounded-xl px-4 py-3 text-[13px] leading-5',
        TRAY[tone]
      )}
    >
      <ToneIcon className={cn('mt-px size-4 shrink-0', GLYPH_TONE[tone])} />
      <p className='min-w-0 text-pretty'>
        <span className='sr-only'>{WORD[tone]}: </span>
        {children}
      </p>
    </div>
  );
}

'use client';

import { cn } from '@/registry/ndeko/lib/utils';
import { CopyButton } from '@/registry/ndeko/ui/copy-button';

export const CODE_TRAY = 'bg-foreground/[0.04] rounded-lg';

export function CodeBlock({ code }: { code: string }) {
  return (
    <div className='relative'>
      <pre
        tabIndex={0}
        className={cn(
          CODE_TRAY,
          'focus-visible:ring-ring/25 relative overflow-x-auto py-2.5 ps-3 pe-10 font-mono text-[12.5px] leading-relaxed outline-none focus-visible:ring-[3px]'
        )}
      >
        <code>{code}</code>
      </pre>
      <CopyButton
        text={code}
        label='Copy the code'
        className='absolute end-1.5 top-1.5'
      />
    </div>
  );
}

import {
  BlocksIcon,
  BookOpenIcon,
  RocketIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';

import type { PageId } from './pages';

export type Manager = 'pnpm' | 'npm' | 'yarn' | 'bun';

export type InstallTab = 'cli' | 'manual';

export const PRODUCT = {
  name: 'Wickerline',
  version: 'v2',
  title: 'Wickerline documentation',
  lead: 'Record what your agents do, and hold the risky steps for a person.',
};

export const SAMPLE_NOTE =
  'Wickerline is an example product. Its pages, keys and addresses are samples.';

export type Category = {
  id: string;
  title: string;
  text: string;
  icon: Icon;
  pageId: PageId;
};

export const CATEGORIES: Category[] = [
  {
    id: 'start',
    title: 'Get started',
    text: 'Install the SDK, add your project key and record a first run.',
    icon: RocketIcon,
    pageId: 'installation',
  },
  {
    id: 'build',
    title: 'Build',
    text: 'Hold a step for a person and answer from your own app.',
    icon: BlocksIcon,
    pageId: 'approvals',
  },
  {
    id: 'reference',
    title: 'Reference',
    text: 'Every event a run sends, with its fields and its retries.',
    icon: BookOpenIcon,
    pageId: 'events',
  },
];

export const SUGGESTIONS = ['install', 'approval', 'retries'];

export const MANAGERS: { value: Manager; label: string }[] = [
  { value: 'pnpm', label: 'pnpm' },
  { value: 'npm', label: 'npm' },
  { value: 'yarn', label: 'yarn' },
  { value: 'bun', label: 'bun' },
];

export const RUNNER: Record<Manager, string> = {
  pnpm: 'pnpm dlx',
  npm: 'npx',
  yarn: 'yarn dlx',
  bun: 'bunx',
};

export const ADDER: Record<Manager, string> = {
  pnpm: 'pnpm add',
  npm: 'npm install',
  yarn: 'yarn add',
  bun: 'bun add',
};

export const INIT_ARGS = 'wickerline init';

export const PACKAGE = '@wickerline/sdk';

export type ManualStep = {
  id: string;
  title: string;
  code?: string;
};

export const MANUAL_STEPS: ManualStep[] = [
  { id: 'package', title: 'Add the package to your project.' },
  {
    id: 'key',
    title: 'Put the project key in your environment.',
    code: 'WICKERLINE_KEY=wl_pk_live_4d1a',
  },
  {
    id: 'record',
    title: 'Start your agent through the recorder.',
    code: "const run = await record('weekly-digest', agent);",
  },
  { id: 'open', title: 'Open the run from your dashboard.' },
];

export const INSTALL_SEARCH_TEXT =
  'Run the command with pnpm, npm, yarn or bun, or add the package by hand.';

export const CLI_NOTE =
  'The command adds the package, asks for your project key and wraps your agent. It asks before it changes a file.';

'use client';

import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/registry/ndeko/ui/table';

import { Callout } from './callout';
import { CodeBlock } from './code-block';
import { InlineText } from './inline-text';
import { Install } from './install';
import type { Block, PageId, PageLink } from './pages';

type InstallProps = React.ComponentProps<typeof Install>;

function TableBlock({ head, rows }: { head: string[]; rows: string[][] }) {
  return (
    <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] overflow-clip rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <Table>
        <TableHeader>
          <TableRow>
            {head.map((title) => (
              <TableHead key={title}>{title}</TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map(([name, meaning]) => (
            <TableRow key={name}>
              <TableCell className='px-3 py-2.5 font-mono text-xs whitespace-nowrap'>
                {name}
              </TableCell>
              <TableCell className='text-muted-foreground px-3 py-2.5'>
                {meaning}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

type LinksBlockProps = {
  links: PageLink[];
  onOpenPage: (pageId: PageId) => void;
};

function LinksBlock({ links, onOpenPage }: LinksBlockProps) {
  return (
    <ul className='flex flex-col'>
      {links.map((link) => {
        function open(event: React.MouseEvent<HTMLAnchorElement>) {
          event.preventDefault();
          onOpenPage(link.pageId);
        }

        return (
          <li key={link.pageId}>
            <a
              href={`#${link.pageId}`}
              onClick={open}
              className={cn(
                'group text-primary-ink inline-flex items-center gap-1.5 rounded-sm py-1 text-[15px] font-medium underline-offset-4 hover:underline',
                FOCUS_RING
              )}
            >
              {link.label}
              <ArrowRightIcon className='size-4 transition-transform duration-100 group-hover:translate-x-0.5' />
            </a>
          </li>
        );
      })}
    </ul>
  );
}

type BlockViewProps = {
  block: Block;
  install: InstallProps;
  onOpenPage: (pageId: PageId) => void;
};

function BlockView({ block, install, onOpenPage }: BlockViewProps) {
  switch (block.kind) {
    case 'text':
      return (
        <p className='text-[15px] leading-7 text-pretty'>
          <InlineText text={block.text} />
        </p>
      );
    case 'list':
      return (
        <ul className='flex flex-col gap-2 text-[15px] leading-6'>
          {block.items.map((item) => (
            <li key={item} className='flex items-baseline gap-3'>
              <span
                aria-hidden='true'
                className='bg-foreground/30 size-1.5 shrink-0 translate-y-[-0.15em] rounded-full'
              />
              <span className='min-w-0'>
                <InlineText text={item} />
              </span>
            </li>
          ))}
        </ul>
      );
    case 'code':
      return <CodeBlock code={block.code} />;
    case 'callout':
      return (
        <Callout tone={block.tone}>
          <InlineText text={block.text} />
        </Callout>
      );
    case 'install':
      return <Install {...install} />;
    case 'table':
      return <TableBlock head={block.head} rows={block.rows} />;
    case 'links':
      return <LinksBlock links={block.links} onOpenPage={onOpenPage} />;
  }
}

type DocBlocksProps = {
  blocks: Block[];
  install: InstallProps;
  onOpenPage: (pageId: PageId) => void;
};

export function DocBlocks({ blocks, install, onOpenPage }: DocBlocksProps) {
  return (
    <>
      {blocks.map((block, index) => (
        <BlockView
          key={index}
          block={block}
          install={install}
          onOpenPage={onOpenPage}
        />
      ))}
    </>
  );
}

'use client';

import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/registry/ndeko/ui/breadcrumb';

import { SAMPLE_NOTE } from './data';
import { DocBlocks } from './doc-blocks';
import { OnThisPage } from './on-this-page';
import { PageFooter } from './page-footer';
import type { DocPage as DocPageContent, PageId } from './pages';

type DocPageProps = {
  page: DocPageContent;
  activeId: string;
  pressed: string | null;
  install: React.ComponentProps<typeof DocBlocks>['install'];
  headingIdOf: (headingId: string) => string;
  onJump: (headingId: string) => void;
  onOpenPage: (pageId: PageId) => void;
  onOpenHome: () => void;
};

export function DocPage({
  page,
  activeId,
  pressed,
  install,
  headingIdOf,
  onJump,
  onOpenPage,
  onOpenHome,
}: DocPageProps) {
  function openHome(event: React.MouseEvent<HTMLAnchorElement>) {
    event.preventDefault();
    onOpenHome();
  }

  return (
    <div className='mx-auto grid max-w-5xl gap-10 px-4 py-8 @2xl:px-8 @5xl:grid-cols-[minmax(0,1fr)_11rem]'>
      <article className='flex min-w-0 flex-col gap-10'>
        <header className='flex flex-col gap-4'>
          <Breadcrumb>
            <BreadcrumbList>
              <BreadcrumbItem>
                <BreadcrumbLink href='#home' onClick={openHome}>
                  Docs
                </BreadcrumbLink>
              </BreadcrumbItem>
              <BreadcrumbSeparator />
              <BreadcrumbItem>{page.category}</BreadcrumbItem>
              <BreadcrumbSeparator />
              <BreadcrumbItem>
                <BreadcrumbPage>{page.title}</BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>
          <h1 className='text-2xl font-semibold text-balance @sm:text-3xl'>
            {page.title}
          </h1>
          <p className='text-muted-foreground text-base leading-7 text-pretty'>
            {page.lead}
          </p>
        </header>
        {page.sections.map((section) => (
          <section key={section.id} className='flex flex-col gap-4'>
            <h2
              id={headingIdOf(section.id)}
              data-heading={section.id}
              tabIndex={-1}
              className={cn(
                'rounded-sm text-xl font-semibold text-balance',
                FOCUS_RING
              )}
            >
              {section.title}
            </h2>
            <DocBlocks
              blocks={section.blocks}
              install={install}
              onOpenPage={onOpenPage}
            />
          </section>
        ))}
        <PageFooter pageId={page.id} pressed={pressed} onOpen={onOpenPage} />
        <p className='text-muted-foreground text-xs'>{SAMPLE_NOTE}</p>
      </article>
      <aside className='hidden @5xl:block'>
        <div className='sticky top-6'>
          <OnThisPage
            sections={page.sections}
            activeId={activeId}
            headingIdOf={headingIdOf}
            onJump={onJump}
          />
        </div>
      </aside>
    </div>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { MenuIcon } from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { PRODUCT } from './data';

type DocsHeaderProps = {
  isHome: boolean;
  pressed: string | null;
  canReplay: boolean;
  onOpenHome: () => void;
  onOpenMenu: () => void;
  onReplay: () => void;
};

function currentOf(isHome: boolean): 'page' | undefined {
  if (isHome) {
    return 'page';
  }
  return undefined;
}

export function DocsHeader({
  isHome,
  pressed,
  canReplay,
  onOpenHome,
  onOpenMenu,
  onReplay,
}: DocsHeaderProps) {
  function openHome(event: React.MouseEvent<HTMLAnchorElement>) {
    event.preventDefault();
    onOpenHome();
  }

  return (
    <header className='hairline-b border-border flex h-14 shrink-0 items-center gap-3 px-4 @2xl:px-6'>
      {!isHome && (
        <Button
          type='button'
          variant='ghost'
          size='icon'
          aria-label='Open the docs menu'
          data-sheet-trigger
          onClick={onOpenMenu}
          className='text-muted-foreground -ms-1.5 @3xl:hidden'
        >
