type InlineTextProps = {
  text: string;
};

/** Words between backticks are code. */
export function InlineText({ text }: InlineTextProps) {
  const pieces = text.split('`');

  return (
    <>
      {pieces.map((piece, index) => {
        const isCode = index % 2 === 1;
        if (isCode) {
          return (
            <code
              key={index}
              className='bg-foreground/[0.06] rounded-[5px] px-1.5 py-0.5 font-mono text-[0.85em]'
            >
              {piece}
            </code>
          );
        }
        return <span key={index}>{piece}</span>;
      })}
    </>
  );
}

'use client';

import { WordRoll, type WordRollWord } from '@/components/core/word-roll';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { CheckIcon, CopyIcon, InfoIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { CopyButton } from '@/registry/ndeko/ui/copy-button';
import { Tabs, TabsList, TabsPanel, TabsTab } from '@/registry/ndeko/ui/tabs';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { CODE_TRAY, CodeBlock } from './code-block';
import {
  ADDER,
  CLI_NOTE,
  INIT_ARGS,
  MANAGERS,
  MANUAL_STEPS,
  PACKAGE,
  RUNNER,
  type InstallTab,
  type Manager,
} from './data';

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

/** The words before the package keep their key while the package manager changes, so only they roll. */
function commandWordsOf(lead: string, rest: string): WordRollWord[] {
  return [
    { key: `lead-${lead}`, text: lead, node: lead },
    { key: 'rest', text: rest, node: rest },
  ];
}

export function initCommandOf(manager: Manager) {
  return `${RUNNER[manager]} ${INIT_ARGS}`;
}

export function addCommandOf(manager: Manager) {
  return `${ADDER[manager]} ${PACKAGE}`;
}

function copyLabelOf(isCopied: boolean) {
  if (isCopied) {
    return 'Copied';
  }
  return 'Copy the command';
}

function managerOf(values: unknown[]) {
  const [value] = values;
  const option = MANAGERS.find((candidate) => candidate.value === value);
  return option?.value;
}

function tabOf(value: unknown): InstallTab | null {
  if (value === 'cli') {
    return 'cli';
  }
  if (value === 'manual') {
    return 'manual';
  }
  return null;
}

type InstallProps = {
  manager: Manager;
  tab: InstallTab;
  isCommandCopied: boolean;
  pressed: string | null;
  onPickManager: (manager: Manager) => void;
  onPickTab: (tab: InstallTab) => void;
  onCopyCommand: () => void;
};

export function Install({
  manager,
  tab,
  isCommandCopied,
  pressed,
  onPickManager,
  onPickTab,
  onCopyCommand,
}: InstallProps) {
  const initWords = commandWordsOf(RUNNER[manager], INIT_ARGS);
  const addWords = commandWordsOf(ADDER[manager], PACKAGE);

  function pickManager(values: unknown[]) {
    const picked = managerOf(values);
    if (picked) {
      onPickManager(picked);
    }
  }

  function pickTab(value: unknown) {
    const picked = tabOf(value);
    if (picked) {
      onPickTab(picked);
    }
  }

  return (
    <Tabs value={tab} onValueChange={pickTab} className='gap-4'>
      <div className='flex flex-wrap items-center justify-between gap-3'>
        <TabsList variant='segmented'>
          <TabsTab
            value='cli'
            className={pressedQuietOf(pressed === 'tab-cli')}
          >
            Command line
          </TabsTab>
          <TabsTab
            value='manual'
            className={pressedQuietOf(pressed === 'tab-manual')}
          >
            By hand
          </TabsTab>
        </TabsList>
        <ToggleGroup
          aria-label='Package manager'
          value={[manager]}
          onValueChange={pickManager}
          travel
          indicatorClassName={THUMB}
          className='bg-foreground/[0.04] rounded-lg p-0.5'
        >
          {MANAGERS.map((option) => (
            <ToggleGroupItem
              key={option.value}
              value={option.value}
              className={cn(
                'h-6 rounded-md px-2.5 font-mono text-xs',
                pressedQuietOf(pressed === `pm-${option.value}`)
              )}
            >
              {option.label}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
      </div>

      <TabsPanel value='cli' className='flex flex-col gap-3'>
        <div
          className={cn(
            CODE_TRAY,
            'relative flex items-center gap-2 py-1.5 ps-3 pe-1.5 font-mono text-[13px]'
          )}
        >
          <span aria-hidden='true' className='text-muted-foreground'>
            $
          </span>
          <code className='relative min-w-0 flex-1 overflow-x-auto py-1 whitespace-nowrap'>
            <WordRoll words={initWords} />
          </code>
          <Button
            type='button'
            variant='ghost'
            size='icon-sm'
            aria-label={copyLabelOf(isCommandCopied)}
            onClick={onCopyCommand}
            className={cn(
              'text-muted-foreground size-7',
              pressedQuietOf(pressed === 'copy-command')
            )}
          >
            <Swap swapKey={String(isCommandCopied)}>
              {isCommandCopied && <CheckIcon className='size-3.5' />}
              {!isCommandCopied && <CopyIcon className='size-3.5' />}
            </Swap>
          </Button>
        </div>
        <p className='bg-info/10 flex items-start gap-3 rounded-xl px-4 py-3 text-[13px] leading-5'>
          <InfoIcon className='text-info-foreground mt-px size-4 shrink-0' />
          <span>{CLI_NOTE}</span>
        </p>
      </TabsPanel>

      <TabsPanel value='manual'>
        <ol className='flex flex-col gap-5'>
          {MANUAL_STEPS.map((step, index) => {
            const isPackageStep = step.id === 'package';
            return (
              <li key={step.id} className='flex gap-3'>
                <span className='keycap-3d text-muted-foreground flex size-6 shrink-0 items-center justify-center rounded-md text-xs font-medium tabular-nums'>
                  {index + 1}
                </span>
                <div className='flex min-w-0 flex-1 flex-col gap-2'>
                  <p className='pt-0.5 text-[13px] leading-5'>{step.title}</p>
                  {isPackageStep && (
                    <div className='relative'>
                      <div
                        className={cn(
                          CODE_TRAY,
                          'relative overflow-x-auto py-2.5 ps-3 pe-10 font-mono text-[12.5px] whitespace-nowrap'
                        )}
                      >
                        <WordRoll words={addWords} />
                      </div>
                      <CopyButton
                        text={addCommandOf(manager)}
                        label='Copy the command'
                        className='absolute end-1.5 top-1.5'
                      />
                    </div>
                  )}
                  {step.code && <CodeBlock code={step.code} />}
                </div>
              </li>
            );
          })}
        </ol>
      </TabsPanel>
    </Tabs>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';
import { useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { INSTANT, SPRING } from '@/registry/ndeko/lib/motion-presets';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';

import type { Section } from './pages';

function travelOf(shouldReduceMotion: boolean): Transition {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return SPRING;
}

function currentOf(isActive: boolean): 'location' | undefined {
  if (isActive) {
    return 'location';
  }
  return undefined;
}

type OnThisPageProps = {
  sections: Section[];
  activeId: string;
  headingIdOf: (headingId: string) => string;
  onJump: (headingId: string) => void;
};

export function OnThisPage({
  sections,
  activeId,
  headingIdOf,
  onJump,
}: OnThisPageProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const markerId = useId();

  return (
    <nav aria-label='On this page' className='flex flex-col gap-3'>
      <p className='text-muted-foreground text-xs font-medium'>On this page</p>
      <ol className='hairline-l border-border flex flex-col'>
        {sections.map((section) => {
          const isActive = section.id === activeId;

          function jump(event: React.MouseEvent<HTMLAnchorElement>) {
            event.preventDefault();
            onJump(section.id);
          }

          return (
            <li key={section.id} className='relative'>
              {isActive && (
                <motion.span
                  layoutId={markerId}
                  transition={travelOf(shouldReduceMotion)}
                  className='bg-primary absolute inset-y-1.5 -start-px w-0.5 rounded-full'
                />
              )}
              <a
                href={`#${headingIdOf(section.id)}`}
                aria-current={currentOf(isActive)}
                onClick={jump}
                className={cn(
                  'text-muted-foreground hover:text-foreground block rounded-sm py-1.5 ps-3 text-[13px] transition-colors duration-150',
                  isActive && 'text-foreground',
                  FOCUS_RING
                )}
              >
                {section.title}
              </a>
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { ArrowLeftIcon, ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';

import { PAGE_ORDER, pageOf, type PageId } from './pages';

const CARD =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

function neighbourOf(pageId: PageId, offset: number) {
  const index = PAGE_ORDER.indexOf(pageId);
  return PAGE_ORDER[index + offset];
}

type PageFooterProps = {
  pageId: PageId;
  pressed: string | null;
  onOpen: (pageId: PageId) => void;
};

export function PageFooter({ pageId, pressed, onOpen }: PageFooterProps) {
  const previousId = neighbourOf(pageId, -1);
  const nextId = neighbourOf(pageId, 1);
  const hasPrevious = previousId !== undefined;
  const hasNext = nextId !== undefined;

  return (
    <nav
      aria-label='Previous and next pages'
      className='grid gap-3 @lg:grid-cols-2'
    >
      {hasPrevious && (
        <a
          href={`#${previousId}`}
          onClick={(event) => {
            event.preventDefault();
            onOpen(previousId);
          }}
          className={cn(
            CARD,
            'group hover:bg-foreground/[0.02] flex flex-col gap-1 p-4 transition-colors duration-100',
            FOCUS_RING,
            pressedQuietOf(pressed === 'previous-page')
          )}
        >
          <span className='text-muted-foreground flex items-center gap-1 text-xs'>
            <ArrowLeftIcon className='size-3.5 transition-transform duration-100 group-hover:-translate-x-0.5' />
            Previous
          </span>
          <span className='text-sm font-medium'>
            {pageOf(previousId).title}
          </span>
        </a>
      )}
      {hasNext && (
        <a
          href={`#${nextId}`}
          onClick={(event) => {
            event.preventDefault();
            onOpen(nextId);
          }}
          className={cn(
            CARD,
            'group hover:bg-foreground/[0.02] flex flex-col gap-1 p-4 transition-colors duration-100 @lg:col-start-2 @lg:items-end @lg:text-end',
            FOCUS_RING,
            pressedQuietOf(pressed === 'next-page')
          )}
        >
          <span className='text-muted-foreground flex items-center gap-1 text-xs'>
            Next
            <ArrowRightIcon className='size-3.5 transition-transform duration-100 group-hover:translate-x-0.5' />
          </span>
          <span className='text-sm font-medium'>{pageOf(nextId).title}</span>
        </a>
      )}
    </nav>
  );
}

