'use client';

import { useRef } from 'react';

import { SearchIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';

type SearchFieldProps = {
  id: string;
  value: string;
  label: string;
  placeholder: string;
  size?: 'default' | 'lg';
  onChange: (query: string) => void;
  onEnter: () => void;
};

export function SearchField({
  id,
  value,
  label,
  placeholder,
  size = 'default',
  onChange,
  onEnter,
}: SearchFieldProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const hasQuery = value !== '';

  function pressKey(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Enter') {
      event.preventDefault();
      onEnter();
      return;
    }
    const clears = event.key === 'Escape' && hasQuery;
    if (clears) {
      event.preventDefault();
      event.stopPropagation();
      onChange('');
    }
  }

  /** The cross leaves with the search it cleared, so its field takes the focus back. */
  function clear() {
    onChange('');
    inputRef.current?.focus();
  }

  return (
    <div className='relative'>
      <label htmlFor={id} className='sr-only'>
        {label}
      </label>
      <SearchIcon className='text-muted-foreground pointer-events-none absolute start-2.5 top-1/2 size-4 -translate-y-1/2' />
      <Input
        ref={inputRef}
        id={id}
        type='search'
        size={size}
        autoComplete='off'
        spellCheck={false}
        placeholder={placeholder}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        onKeyDown={pressKey}
        className='ps-8 pe-8'
      />
      {hasQuery && (
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label='Clear the search'
          onClick={clear}
          className='text-muted-foreground absolute end-1 top-1/2 size-6 -translate-y-1/2'
        >
          <XIcon className='size-3.5' />
        </Button>
      )}
    </div>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { nounOf } from '@/registry/ndeko/lib/words';

import { markedPartsOf, searchOf, wordsOf, type SearchResult } from './search';

export function Marked({ text, words }: { text: string; words: string[] }) {
  const parts = markedPartsOf(text, words);

  return (
    <>
      {parts.map((part) => {
        if (part.isMatch) {
          return (
            <mark
              key={part.key}
              className='bg-primary/15 text-foreground rounded-[3px]'
            >
              {part.text}
            </mark>
          );
        }
        return <span key={part.key}>{part.text}</span>;
      })}
    </>
  );
}

function hrefOf(result: SearchResult) {
  const { entry } = result;
  if (entry.headingId === null) {
    return `#${entry.pageId}`;
  }
  return `#${entry.pageId}-${entry.headingId}`;
}

type SearchResultsProps = {
  query: string;
  pressed: string | null;
  onOpen: (result: SearchResult) => void;
  onClear: () => void;
};

export function SearchResults({
  query,
  pressed,
  onOpen,
  onClear,
}: SearchResultsProps) {
  const words = wordsOf(query);
  const results = searchOf(query);
  const hasResults = results.length > 0;
  const hasWords = words.length > 0;
  const noun = nounOf(results.length, 'result');

  if (!hasWords) {
    return null;
  }
  if (!hasResults) {
    return (
      <div className='flex flex-col items-start gap-2'>
        <p className='text-muted-foreground text-[13px] text-pretty'>
          No page holds “{query.trim()}”.
        </p>
        <button
          type='button'
          onClick={onClear}
          className={cn(
            'text-primary-ink rounded-sm text-xs font-medium underline-offset-4 hover:underline',
            FOCUS_RING
          )}
        >
          Clear the search
        </button>
      </div>
    );
  }

  return (
    <div className='flex flex-col gap-1.5'>
      <p className='text-muted-foreground flex items-baseline gap-1 px-2 text-xs'>
        <MotionNumber value={results.length} />
        {noun}
      </p>
      <ul aria-label='Search results' className='flex flex-col'>
        {results.map((result, index) => {
          const { entry } = result;

          function open(event: React.MouseEvent<HTMLAnchorElement>) {
            event.preventDefault();
            onOpen(result);
          }

          return (
            <li key={entry.key}>
              <a
                href={hrefOf(result)}
                onClick={open}
                className={cn(
                  'hover:bg-foreground/[0.04] flex flex-col gap-0.5 rounded-lg px-2 py-2 text-start transition-colors duration-100',
                  FOCUS_RING,
                  pressedQuietOf(pressed === `result-${index}`)
                )}
              >
                <span className='text-[13px] leading-5 font-medium'>
                  <Marked text={entry.title} words={words} />
                </span>
                <span className='text-muted-foreground text-xs'>
                  {entry.crumb}
                </span>
                <span className='text-muted-foreground text-xs leading-5 text-pretty'>
                  <Marked text={result.snippet} words={words} />
                </span>
              </a>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { INSTALL_SEARCH_TEXT } from './data';
import { PAGES, type Block, type DocPage, type PageId } from './pages';

export type SearchEntry = {
  key: string;
  pageId: PageId;
  headingId: string | null;
  title: string;
  crumb: string;
  text: string;
};

export type SearchResult = {
  entry: SearchEntry;
  snippet: string;
};

export type MarkedPart = {
  key: string;
  text: string;
  isMatch: boolean;
};

type Range = {
  start: number;
  end: number;
};

/** A single letter matches nearly every page, so a word counts from two letters. */
const MIN_WORD_LENGTH = 2;

const MAX_RESULTS = 6;

const SNIPPET_BEFORE = 36;

const SNIPPET_LENGTH = 116;

function plainOf(text: string) {
  return text.replaceAll('`', '');
}

function textOfBlock(block: Block) {
  switch (block.kind) {
    case 'text':
      return plainOf(block.text);
    case 'list':
      return plainOf(block.items.join('. '));
    case 'code':
      return plainOf(block.code);
    case 'callout':
      return plainOf(block.text);
    case 'install':
      return INSTALL_SEARCH_TEXT;
    case 'table': {
      const rows = block.rows.map((row) => row.join(', '));
      return rows.join('. ');
    }
    case 'links': {
      const labels = block.links.map((link) => link.label);
      return labels.join('. ');
    }
  }
}

function entriesOfPage(page: DocPage): SearchEntry[] {
  const pageEntry: SearchEntry = {
    key: page.id,
    pageId: page.id,
    headingId: null,
    title: page.title,
    crumb: page.category,
    text: page.lead,
  };
  const sectionEntries = page.sections.map((section) => {
    const texts = section.blocks.map(textOfBlock);
    const entry: SearchEntry = {
      key: `${page.id}:${section.id}`,
      pageId: page.id,
      headingId: section.id,
      title: section.title,
      crumb: `${page.category} / ${page.title}`,
      text: texts.join(' '),
    };
    return entry;
  });
  return [pageEntry, ...sectionEntries];
}

const ENTRIES = PAGES.flatMap(entriesOfPage);

export function wordsOf(query: string) {
  const lowered = query.toLowerCase();
  const pieces = lowered.split(/\s+/);
  return pieces.filter((piece) => piece.length >= MIN_WORD_LENGTH);
}

function scoreOf(entry: SearchEntry, words: string[]) {
  const title = entry.title.toLowerCase();
  const text = entry.text.toLowerCase();
  let score = 0;
  for (const word of words) {
    const isInTitle = title.includes(word);
    const isInText = text.includes(word);
    if (!isInTitle && !isInText) {
      return 0;
    }
    if (isInTitle) {
      score += 3;
    }
    if (isInText) {
      score += 1;
    }
  }
  return score;
}

function firstMatchOf(lowered: string, words: string[]) {
  let first = -1;
  for (const word of words) {
    const at = lowered.indexOf(word);
    const isFound = at !== -1;
    const isEarlier = first === -1 || at < first;
    if (isFound && isEarlier) {
      first = at;
    }
  }
  return first;
}

function ellipsisIf(isCut: boolean) {
  if (isCut) {
    return '…';
  }
  return '';
}

function snippetOf(text: string, words: string[]) {
  const first = firstMatchOf(text.toLowerCase(), words);
  const wanted = first - SNIPPET_BEFORE;
  const start = Math.max(0, wanted);
  const end = Math.min(text.length, start + SNIPPET_LENGTH);
  const slice = text.slice(start, end).trim();
  const before = ellipsisIf(start > 0);
  const after = ellipsisIf(end < text.length);
  return `${before}${slice}${after}`;
}

type Scored = {
  entry: SearchEntry;
  score: number;
};

function hasScore(scored: Scored) {
  return scored.score > 0;
}

function byScore(first: Scored, second: Scored) {
  return second.score - first.score;
}

export function searchOf(query: string): SearchResult[] {
  const words = wordsOf(query);
  if (words.length === 0) {
    return [];
  }
  const scored = ENTRIES.map((entry) => ({
    entry,
    score: scoreOf(entry, words),
  }));
  const matching = scored.filter(hasScore).sort(byScore);
  return matching.slice(0, MAX_RESULTS).map(({ entry }) => ({
    entry,
    snippet: snippetOf(entry.text, words),
  }));
}

function rangesOfWord(lowered: string, word: string) {
  const ranges: Range[] = [];
  let start = lowered.indexOf(word);
  while (start !== -1) {
    const end = start + word.length;
    ranges.push({ start, end });
    start = lowered.indexOf(word, end);
  }
  return ranges;
}

function byStart(first: Range, second: Range) {
  return first.start - second.start;
}

function mergedRanges(ranges: Range[]) {
  const sorted = [...ranges].sort(byStart);
  const merged: Range[] = [];
  for (const range of sorted) {
    const last = merged.at(-1);
    const overlaps = last !== undefined && range.start <= last.end;
    if (overlaps) {
      last.end = Math.max(last.end, range.end);
      continue;
    }
    merged.push({ ...range });
  }
  return merged;
}

export function markedPartsOf(text: string, words: string[]) {
  const lowered = text.toLowerCase();
  const ranges = words.flatMap((word) => rangesOfWord(lowered, word));
  const parts: MarkedPart[] = [];
  let cursor = 0;
  for (const range of mergedRanges(ranges)) {
    if (range.start > cursor) {
      const plain = text.slice(cursor, range.start);
      parts.push({ key: String(cursor), text: plain, isMatch: false });
    }
    const match = text.slice(range.start, range.end);
    parts.push({ key: String(range.start), text: match, isMatch: true });
    cursor = range.end;
  }
  if (cursor < text.length) {
    const rest = text.slice(cursor);
    parts.push({ key: String(cursor), text: rest, isMatch: false });
  }
  return parts;
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';
import { countOf } from '@/registry/ndeko/lib/words';

import type { InstallTab, Manager } from './data';
import { pageOf, type PageId } from './pages';
import { searchOf } from './search';

export type Route = 'home' | PageId;

export type DocsState = {
  route: Route;
  query: string;
  manager: Manager;
  installTab: InstallTab;
  isCommandCopied: boolean;
  /** The heading the frame scrolls to, or the top of the page. */
  readTo: string;
  /** Counts the requests, so asking twice for the same place still scrolls. */
  readRequest: number;
  isNavOpen: boolean;
  spoken: string;
};

export type DocsAction =
  | { type: 'searched'; query: string }
  | { type: 'opened'; route: Route; heading?: string }
  | { type: 'managerPicked'; manager: Manager }
  | { type: 'tabPicked'; tab: InstallTab }
  | { type: 'commandCopied' }
  | { type: 'commandReset' }
  | { type: 'readTo'; heading: string }
  | { type: 'nav'; isOpen: boolean };

type Step = SessionStep<DocsState, DocsAction>;

export const TOP = 'top';

export const INITIAL: DocsState = {
  route: 'home',
  query: '',
  manager: 'pnpm',
  installTab: 'cli',
  isCommandCopied: false,
  readTo: TOP,
  readRequest: 0,
  isNavOpen: false,
  spoken: '',
};

function resultsLineOf(query: string) {
  const results = searchOf(query);
  if (query.trim() === '') {
    return '';
  }
  if (results.length === 0) {
    return 'No page matches';
  }
  return countOf(results.length, 'result');
}

function openedLineOf(route: Route) {
  if (route === 'home') {
    return 'Docs home';
  }
  return pageOf(route).title;
}

function opened(
  state: DocsState,
  route: Route,
  heading: string | undefined
): DocsState {
  const readTo = heading ?? TOP;
  return {
    ...state,
    route,
    query: '',
    readTo,
    readRequest: state.readRequest + 1,
    isNavOpen: false,
    spoken: openedLineOf(route),
  };
}

export function reducer(state: DocsState, action: DocsAction): DocsState {
  switch (action.type) {
    case 'searched':
      return {
        ...state,
        query: action.query,
        spoken: resultsLineOf(action.query),
      };
    case 'opened':
      return opened(state, action.route, action.heading);
    case 'managerPicked':
      return { ...state, manager: action.manager, isCommandCopied: false };
    case 'tabPicked':
      return { ...state, installTab: action.tab };
    case 'commandCopied':
      return { ...state, isCommandCopied: true, spoken: 'Command copied' };
    case 'commandReset':
      return { ...state, isCommandCopied: false };
    case 'readTo':
      return {
        ...state,
        readTo: action.heading,
        readRequest: state.readRequest + 1,
      };
    case 'nav':
      return { ...state, isNavOpen: action.isOpen };
  }
}

const KEY_MS = 110;

function typing(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((query, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'searched', query },
  }));
}

function open(
  after: number,
  press: string,
  route: Route,
  heading?: string
): Step {
  return {
    after,
    by: 'demo',
    press,
    action: { type: 'opened', route, heading },
  };
}

function manager(after: number, value: Manager): Step {
  return {
    after,
    by: 'demo',
    press: `pm-${value}`,
    action: { type: 'managerPicked', manager: value },
  };
}

function tab(after: number, value: InstallTab): Step {
  return {
    after,
    by: 'demo',
    press: `tab-${value}`,
    action: { type: 'tabPicked', tab: value },
  };
}

function readTo(after: number, heading: string): Step {
  return { after, by: 'demo', action: { type: 'readTo', heading } };
}

function nav(after: number, isOpen: boolean): Step {
  return { after, by: 'demo', action: { type: 'nav', isOpen } };
}

/**
 * A developer searches the home page for install, opens the page, switches to bun and copies the
 * command, reads the manual steps, goes on to the next page, finds the timeout of an approval in
 * the sidebar and goes back home. On a phone the sidebar is the sheet the demonstration opens.
 */
export const SCRIPT: Step[] = [
  ...typing('install', 1500),
  open(1700, 'result-0', 'installation'),
  manager(1700, 'bun'),
  {
    after: 1200,
    by: 'demo',
    press: 'copy-command',
    action: { type: 'commandCopied' },
  },
  tab(1700, 'manual'),
  readTo(1600, 'key'),
  open(1800, 'next-page', 'approvals'),
  nav(1400, true),
  ...typing('timeout', 600),
  open(1700, 'result-0', 'approvals', 'timeout'),
  open(3000, 'brand', 'home'),
];

/** Under reduced motion the docs rest on the installation page, with every part of a page in view. */
export const RESTING: DocsState = { ...INITIAL, route: 'installation' };

export const LOOP_AFTER_MS = 2400;
